"""Keep the established A2 reader design; only unit-specific content changes."""
from pathlib import Path
import json,re
ROOT=Path('kitaplar/lise-a2/spor-ve-saglik')
answers={}
def add(n,title,items,note=None):
 answers[str(n)]={'sections':[{'title':title,'items':items}]}
 if note:answers[str(n)]['note']=note
add(1,'Hazırlık · Örnek cevaplar',['Yiyecekler, spor yapan insanlar, mutfak araçları ve sağlık görselleri görüyorum.','Düzenli beslenme ve sporla ilgili kelimeleri; sipariş vermeyi ve tarif anlatmayı çalışacağız.'],'Kişisel sorular için örnek cevaplardır.')
add(2,'Menüler · Metne dayalı cevaplar',['Birinci ve ikinci menü 30 TL, üçüncü menü 25 TL.','Hazırlama süreleri sırayla 20, 15 ve 10 dakika.','Birinci menüde çay, ikinci menüde patates kızartması ikram ediliyor.','Yiyecek tercihi ve gerekçesi kişiseldir. Sepetler: sebze, ekmek, meyve, et ürünleri, yumurta, süt ürünleri.'])
add(3,'Okuma · İçerik',['1 numaralı bölüm Japon beslenme kültürünü, 2 numaralı bölüm Pakistan mutfağını anlatıyor. İzlanda ile ilgili bölüm sonraki sayfada.','Metindeki temel konu beslenme alışkanlıkları ve sağlıklı beslenme kurallarıdır.'],'Sorular metne göre değerlendirilir. Bu bölüm kaynak metnin içerik özetidir.')
add(4,'4. etkinlik · Okuduğunu anlama',['1-b; 2-d; 4-c; 5-a; 6-a.','3. soruda c seçeneği metinden çıkarılamaz. d seçeneği de “%80 doygunluk” ile “yemeğin %80’ini yemek” ifadelerini karıştırır; sorunun tek doğru cevaplı yapısı tartışmalıdır.','5 ve 6. etkinliklerde karşılaştırma ve kişisel beslenme listeleri öğrencinin cevabına göre değerlendirilir.'])
add(5,'Menü ve diyalog · Örnekler',['Menüde çorbalar, sulu yemekler, kebaplar, pideler, tatlılar ve içecekler var.','Sipariş: Büşra mercimek çorbası ve lahmacun; Sena kıymalı pide ve ayran istiyor.','Hazırlama yaklaşık 20 dakika sürüyor. Sütlaç lokantanın ikramıdır.','Örnek: “Menüyü alabilir miyiz?” — “Bir porsiyon kıymalı pide istiyorum.” — “Hesabı alabilir miyiz?”'],'Besin görselleri birden fazla besin öğesi içerebilir. Protein, yağ, vitamin ve mineral sınıfları mutlak biçimde tek bir yiyeceğe özgü değildir.')
add(6,'Dinleme · Kontrol durumu',['S.051 özgün kaydı henüz temin edilmedi. Miktarlar, toplam ödeme, ödeme biçimi ve sürpriz tarifle ilgili kesin dinleme cevapları tahmin edilmedi.','Alışveriş öncesi konuşma soruları kişiseldir.'],'Kaynak metnin ses kaydı geldikten sonra dinlemeye bağlı yanıtlar doğrulanabilir.')
add(7,'Söz varlığı ve tarif',['Alışveriş listesi: 1. paket; 2. şişe; 3. koli; 4. kutu; 5. konserve; 6. kavanoz.','Cümleler için örnekler: b. doğrayalım; c. çırpalım; ç. ekleyelim; d. kaynatalım; e. karıştırarak.','Çilekli Ballı Ayran boşlukları: İlk önce — ekliyoruz — karıştırıyoruz — birkaç — ekleyip.','Hazırlama fiilleri görselleri soldan sağa: pişirmek, kaynatmak, doğramak, eklemek/koymak, çırpmak, karıştırmak.'],'Bazı cümlelerde aynı anlamı taşıyan farklı çekimler de kabul edilebilir.')
add(8,'Market fiyatları ve bütçe',['Makarna: 1. market 5 TL, 2. market 8 TL; 1. market daha ucuz.','Yumurta: 40/38 TL; 2. market daha ucuz. Domates: kilogramı 10/12 TL; 1. market daha ucuz.','Bal: kavanozu 35/30 TL; 2. market daha ucuz. Yoğurt: 1 kg 7 TL / 3 kg 15 TL; kilogram başına 2. market daha ucuz.','Ayran: litresi 7/9 TL; 1. market daha ucuz. Meyve suyu: litresi 9/10 TL; 1. market daha ucuz.','Örnek beş ürün: makarna 5 + domates 10 + yoğurt 7 + süt 7 + ayran 7 = 36 TL.'],'Bütçe ve tavsiye soruları için farklı, gerekçeli cevaplar kabul edilir.')
add(9,'Tarif yazma · Örnek',['Örnek anlatım: Önce yumurtaları çırpın. Sütü ve diğer malzemeleri ekleyip karıştırın. Karışımı kalıba dökün ve pişirin.','Resimde verilen miktar 3 yumurtadır. Diğer dinleme miktarları özgün kayıt olmadan kesinleştirilmedi.','Kendi kültürünüzdeki bir tatlıyı malzemeleri ve hazırlama sırasıyla tanıtabilirsiniz.'],'Bu örnek anlatım özgün dinlemenin cevap anahtarı değildir.')
add(10,'Röportaj · Soru yerleştirme',['İlk soru 1 olarak verilmiştir. Kalan boşlukların sırası: 2 — 5 — 4 — 3 — 6.','Röportajdaki temel öğütler: hedef belirlemek, yeteneklere uygun seçim yapmak, düzenli çalışmak ve iyi insanları örnek almak.'],'S.052 ses kaydı temin edilmedi; cevaplar sayfadaki yazılı röportaja göre hazırlanmıştır.')
add(11,'Okuma · Cevaplar',['3. etkinlik: 1. Çocukluğundan beri / yaklaşık 20–21 yıldır. 2. Haftada beş gün. 3. Günlük saat sayısı metinde verilmemiş. 4. Günde altı öğün; ana ve ara öğünler.','5. Protein grubuna daha çok yer veriyor. 6. Sebze suyu. 7. Zidan/Zidane. 8. Hedef belirlemek, yeteneklere uygun seçim yapmak, düzenli ve çok çalışmak.','4. etkinlik: 1-d. 2. Pasta, kola, kek, tereyağı. 3. Et, süt, yumurta, balık.','Söz varlığı: doğmuş → dünyaya gelmiş; ünlü → meşhur; misafirlerimiz → konuklarımız; kesinlikle → mutlaka.'],'Kişisel egzersiz ve beslenme programı açık uçludur.')
add(12,'Kelime türetme ve dinleme',['Örnek türetmeler: başarı → başarılı / başarısız; yetenek → yetenekli / yeteneksiz; sağlık → sağlıklı / sağlıksız; düzen → düzenli / düzensiz.','S.053 kaydı temin edilmediği için konuşmacı adları, istekler ve tarif ayrıntıları kesinleştirilmedi.'])
add(13,'Kişisel bakım · Kontrol durumu',['Görseller ve kendi alışkanlıklarınız hakkında kişisel cevaplar verebilirsiniz.','Malzeme–miktar eşleştirmeleri, tariflerin dağılımı ve doğru/yanlış maddeleri S.053 kaydına bağlıdır; özgün kayıt olmadan doğru cevap olarak sunulmadı.'],'Kaynakta verilen bakım tarifleri bu çalışmada tıbbi öneri olarak doğrulanmış değildir.')
add(14,'Oyun',['Yazı: 1 birim; tura: 2 birim ilerleme.','Yiyecek ve egzersiz süreleri oyun sonunda her oyuncunun topladığı kutulara göre hesaplanır.','Meyve, sebze, egzersiz ve abur cubur karşılaştırmalarında tek bir sabit sonuç yoktur.'])
add(15,'Sağlıklı yaşam anketi',['8 veya 7 seçenek: Mükemmel; 6, 5 veya 4 seçenek: Güzel; 3, 2 veya 1 seçenek: Hayat kalitesini artırmaya yönelik öneri bölümü.','Görsel eşleştirmeleri: meyve tabağı → sağlıklı beslenme; yatak → uyku düzeni; telefon kullanan kişiler → teknolojinin bilinçli kullanımı; spor yapan kişi → düzenli spor; resim yapan kişi → hobi edinme; birlikte sohbet edenler → sosyal ilişkiler; doğada oturanlar → doğa ile iç içe olma; hayvanlarla olan kişi → hayvanlarla vakit geçirme.'],'Görsel tanımları ile değerlendirin; öğrencinin kişisel anket sonucu değişir.')
add(16,'Şemalardaki bilgiler',['Yüzme şemasında: kemikler, kilo kontrolü, uyku, mide, akciğerler, ruh hâli, bağırsaklar, kaslar ve kalp.','Koşma şemasında: kemikler ve kaslar, kalp, akciğerler/astım, bağışıklık sistemi, kilo kontrolü ve zihin sağlığı.','Türkü sözleri sayfada bulunuyor. M.006 özgün müzik kaydı temin edilmedi.'],'Bu liste kaynak şemada yazanları aktarır; sağlık iddialarına bağımsız tıbbi doğrulama yapıldığı anlamına gelmez.')
add(17,'Bilgi paylaşımı · Kaynağa göre',['İki şemada da kalp, akciğerler, kemikler/kaslar ve kilo kontrolü yer alıyor.','Bağırsaklar, uyku ve ruh hâli yüzme şemasında; zihin sağlığı koşma şemasında açıkça belirtiliyor.','Şemada belirtilmeyen bir yarar için kesin “yoktur” sonucu çıkarmayın; “bu şemada belirtilmemiş” denebilir.','Sağlıklı yaşam alışkanlıkları hakkındaki son etkinlik kişiseldir.'])
add(18,'Yazma · Kontrol listesi',['Tarifte malzemeleri, miktarları ve hazırlama sırasını yazın. Örnek başlangıç: “Bir kase yoğurda bir kaşık bal ekliyorum.”','Hidayet Türkoğlu yazısında doğum, meslek ve başarı bilgilerini araştırdığınız kaynakla doğrulayın. Günlük programını kaynak bulunmadan kesin bilgi gibi yazmayın.'],'Açık uçlu yazma etkinlikleridir; tek bir sabit metin aranmaz.')
add(19,'Video · Kontrol durumu',['V.009 özgün videosu temin edilmedi. Biber’in rüyası, yarışma ve börek tercihleri hakkındaki cevaplar tahmin edilmedi.','Sebze tercihleri ve videoya verilen puan kişiseldir.'])
add(20,'Proje · Kontrol listesi',['Bir yemek seçtim; malzemelerini ve miktarlarını belirledim.','Hazırlama aşamalarını önce, sonra, ardından, en son gibi ifadelerle anlattım.','Videoyu düzenledim ve sınıfta sundum.','Çekimde karşılaştığım durumları ve çekim hikâyesini anlattım.'],'Proje açık uçludur; liste örnektir.')
(ROOT/'answers.json').write_text(json.dumps(answers,ensure_ascii=False,separators=(',',':')))
h=Path('kitaplar/lise-a2/akilli-teknoloji/index.html').read_text()
h=h.replace('akilli-teknoloji','spor-ve-saglik').replace('Akıllı Teknoloji','Spor ve Sağlık').replace('7. Ünite','8. Ünite').replace('7. ünite','8. ünite').replace('7. ÜNİTE','8. ÜNİTE').replace('pages/page-001.webp','pages/sayfa-01.webp')
h=h.replace('href="../hayat-birlikte-guzel/"','href="../akilli-teknoloji/"').replace('title="8. ünite henüz hazırlanmadı"','title="9. ünite henüz hazırlanmadı"')
h=re.sub(r'<nav class="unit-navigation" aria-label="Üniteler arasında geçiş">.*?</nav>','<nav class="unit-navigation" aria-label="Üniteler arasında geçiş"><a class="unit-nav-button" href="../akilli-teknoloji/">← Bir Önceki Ünite</a><button class="unit-nav-button" disabled title="9. ünite henüz hazırlanmadı">Bir Sonraki Ünite →</button></nav>',h,count=1)
