# Enable only the now-built unit, without changing any style or other levels.
p=Path('index.html');h=p.read_text().replace('const available=i<=6;','const available=i<=7;');p.write_text(h)
p=Path('kitaplar/lise-a2/akilli-teknoloji/index.html');h=p.read_text().replace('<button class="unit-nav-button" disabled title="8. ünite henüz hazırlanmadı">Bir Sonraki Ünite →</button>','<a class="unit-nav-button" href="../spor-ve-saglik/">Bir Sonraki Ünite →</a>');p.write_text(h)
